def sig(ops, z):
    try:
        return ops.np.sigmoid(z)
    except:
        pass
    try:
        return ops.np.expit(z)
    except:
        pass
    try:
        return ops.np.logistic(z)
    except:
        pass
    return ops.np.divide(1.0, ops.np.add(1.0, ops.np.exp(ops.np.negative(z))))

def init(sizes, ops):
    d = int(sizes['d'])
    V = int(sizes['V'])
    params = {
        'd': d, 'V': V,
        'Wr': ops.np.normal((d, 2 * d), 1, 0.3), 'br': ops.np.normal((d,), 2, 0.1),
        'Wi': ops.np.normal((d, 2 * d), 3, 0.3), 'bi': ops.np.normal((d,), 4, 0.1),
        'Wo': ops.np.normal((d, 2 * d), 5, 0.3), 'bo': ops.np.normal((d,), 6, 0.1),
        'Wu': ops.np.normal((d, 2 * d), 7, 0.3), 'bu': ops.np.normal((d,), 8, 0.1),
        'E': ops.np.normal((V, d), 9, 1.0),
        'O': ops.np.normal((d, V), 10, 0.3),
    }
    state = {
        's': ops.np.zeros(d), 'y': ops.np.zeros(d), 'buf': ops.np.zeros(2 * d),
        'r': ops.np.zeros(d), 'i': ops.np.zeros(d), 'o': ops.np.zeros(d), 'u': ops.np.zeros(d),
        'w': ops.np.zeros(3),
    }
    return params, state

def update(params, state, token, ops):
    d = params['d']
    buf = state['buf']
    buf[:d] = state['y']
    buf[d:] = params['E'][int(token)]
    state['r'][:] = sig(ops, ops.np.add(ops.np.matmul(params['Wr'], buf), params['br']))
    state['i'][:] = sig(ops, ops.np.add(ops.np.matmul(params['Wi'], buf), params['bi']))
    state['o'][:] = sig(ops, ops.np.add(ops.np.matmul(params['Wo'], buf), params['bo']))
    state['u'][:] = ops.np.tanh(ops.np.add(ops.np.matmul(params['Wu'], buf), params['bu']))
    state['s'][:] = ops.np.add(ops.np.multiply(state['r'], state['s']), ops.np.multiply(state['i'], state['u']))
    state['y'][:] = ops.np.multiply(state['o'], ops.np.tanh(state['s']))
    return state

def predict(params, state, ops):
    logits = ops.np.matmul(state['y'], params['O'])
    return int(ops.np.argmax(logits))

def get_sig(ops):
    f = None
    try:
        f = ops.np.sigmoid
    except:
        f = None
    if f is None:
        try:
            f = ops.np.expit
        except:
            f = None
    return f

def sigm(ops, z):
    np = ops.np
    f = get_sig(ops)
    if f is not None:
        return f(z)
    return np.divide(1.0, np.add(1.0, np.exp(np.negative(z))))

def affine(ops, W, b, buf):
    np = ops.np
    return np.add(np.sum(np.multiply(W, buf), axis=1), b)

def init(sizes, ops):
    np = ops.np
    d = int(sizes['d'])
    V = int(sizes['V'])
    sc = 1.0 / (2.0 * d) ** 0.5
    params = {'d': d, 'V': V,
              'E': np.normal((V, d), 1, 1.0),
              'Wr': np.normal((d, 2 * d), 2, sc), 'br': np.normal((d,), 3, 0.1),
              'Wi': np.normal((d, 2 * d), 4, sc), 'bi': np.normal((d,), 5, 0.1),
              'Wo': np.normal((d, 2 * d), 6, sc), 'bo': np.normal((d,), 7, 0.1),
              'Wu': np.normal((d, 2 * d), 8, sc), 'bu': np.normal((d,), 9, 0.1),
              'Ot': np.normal((V, d), 10, 1.0 / d ** 0.5)}
    z = np.normal((d,), 11, 0.0)
    state = {'s': z, 'y': np.normal((d,), 12, 0.0), 'buf': np.normal((2 * d,), 13, 0.0),
             'r': np.normal((d,), 14, 0.0), 'i': np.normal((d,), 15, 0.0),
             'o': np.normal((d,), 16, 0.0), 'u': np.normal((d,), 17, 0.0),
             'work': [0.0, 0.0, 0.0]}
    return params, state

def update(params, state, token, ops):
    np = ops.np
    buf = np.concatenate([state['y'], params['E'][int(token)]])
    r = sigm(ops, affine(ops, params['Wr'], params['br'], buf))
    i = sigm(ops, affine(ops, params['Wi'], params['bi'], buf))
    o = sigm(ops, affine(ops, params['Wo'], params['bo'], buf))
    u = np.tanh(affine(ops, params['Wu'], params['bu'], buf))
    s = np.add(np.multiply(r, state['s']), np.multiply(i, u))
    y = np.multiply(o, np.tanh(s))
    return {'s': s, 'y': y, 'buf': buf, 'r': r, 'i': i, 'o': o, 'u': u, 'work': state['work']}

def predict(params, state, ops):
    np = ops.np
    logits = np.sum(np.multiply(params['Ot'], state['y']), axis=1)
    return int(np.argmax(logits))

def init(sizes, ops):
    d = sizes["d"]
    V = sizes["V"]
    params = {
        "E": ops.np.normal((V, d), 1, 0.5),
        "W": [ops.np.normal((d, 2 * d), 2 + k, 0.3) for k in range(4)],
        "b": [ops.np.normal((d,), 10 + k, 0.1) for k in range(4)],
        "O": ops.np.normal((V, d), 20, 0.5),
        "d": d,
        "V": V,
    }
    state = {
        "s": ops.np.zeros(d),
        "y": ops.np.zeros(d),
        "z": ops.np.zeros(2 * d),
        "r": ops.np.zeros(d),
        "i": ops.np.zeros(d),
        "o": ops.np.zeros(d),
        "u": ops.np.zeros(d),
        "w": ops.np.zeros(3),
    }
    return params, state


def sig(ops, x):
    try:
        return ops.np.sigmoid(x)
    except:
        pass
    try:
        return ops.np.expit(x)
    except:
        pass
    try:
        return ops.sigmoid(x)
    except:
        pass
    try:
        return ops.expit(x)
    except:
        pass
    # fallback: parameters of the switches are stored negated, so sigma(pre) = 1/(1+exp(x))
    return ops.np.divide(1.0, ops.np.add(1.0, ops.np.exp(x)))


def affine(ops, W, b, z):
    return ops.np.add(ops.np.dot(W, z), b)


def update(params, state, token, ops):
    d = params["d"]
    W = params["W"]
    b = params["b"]
    z = state["z"]
    z[:d] = state["y"]
    z[d:] = params["E"][token]
    r = state["r"]
    i = state["i"]
    o = state["o"]
    u = state["u"]
    r[:] = sig(ops, affine(ops, W[0], b[0], z))
    i[:] = sig(ops, affine(ops, W[1], b[1], z))
    o[:] = sig(ops, affine(ops, W[2], b[2], z))
    u[:] = ops.np.tanh(affine(ops, W[3], b[3], z))
    s = state["s"]
    s[:] = ops.np.add(ops.np.multiply(r, s), ops.np.multiply(i, u))
    y = state["y"]
    y[:] = ops.np.multiply(o, ops.np.tanh(s))
    return state


def predict(params, state, ops):
    O = params["O"]
    y = state["y"]
    w = state["w"]
    for v in range(params["V"]):
        w[2] = ops.np.dot(O[v], y)
        if v == 0:
            w[0] = w[2]
            w[1] = 0
        else:
            if ops.np.greater(w[2], w[0]):
                w[0] = w[2]
                w[1] = v
    return int(w[1])

