C = 0.01
BASE = 5.0

def sig(x):
    return (1.0 / (1.0 + np.exp(-x))).astype(np.float32)

def cell(s, y, pr, pi, po, pu):
    r = sig(pr)
    i = sig(pi)
    o = sig(po)
    u = np.tanh(pu).astype(np.float32)
    s2 = (r * s + i * u).astype(np.float32)
    y2 = (o * np.tanh(s2)).astype(np.float32)
    return s2, y2

def full(v):
    return np.full(8, v, dtype=np.float32)

def init(layout):
    return {"s": np.zeros(8, dtype=np.float32), "y": np.zeros(8, dtype=np.float32),
            "n": 0, "m": -1, "sep": int(layout["SEP"])}

def update(state, token):
    s = state["s"]
    y = state["y"]
    n = state["n"]
    m = state["m"]
    sep = state["sep"]
    token = int(token)
    pr = full(40.0)
    pi = full(-40.0)
    po = full(-40.0)
    pu = full(0.0)
    if m < 0:
        if token != sep:
            v = min(max(token, 0), 3)
            k = min(n // 8, 7)
            j = n % 8
            g = 2.0 * C * BASE ** (-j)
            pi[k] = np.float32(np.log(g / (1.0 - g)))
            pu[k] = np.float32(np.arctanh((v - 1.5) / 2.0))
            s2, y2 = cell(s, y, pr, pi, po, pu)
            return {"s": s2, "y": y2, "n": n + 1, "m": -1, "sep": sep}
        po[0] = 40.0
        s2, y2 = cell(s, y, pr, pi, po, pu)
        return {"s": s2, "y": y2, "n": n, "m": 0, "sep": sep}
    m2 = m + 1
    k = min(m2 // 8, 7)
    po[k] = 40.0
    if m2 % 8 != 0:
        v = min(max(token, 0), 3)
        ct = np.tanh(np.float32(C * (v - 1.5))).astype(np.float32)
        pr[k] = -40.0
        pi[k] = 40.0
        pu[k] = np.float32(BASE) * (y[k] - ct)
    s2, y2 = cell(s, y, pr, pi, po, pu)
    return {"s": s2, "y": y2, "n": n, "m": m2, "sep": sep}

def predict(state):
    if state["m"] < 0:
        return 0
    y64 = state["y"].astype(np.float64)
    c = np.tanh(C * (np.arange(4) - 1.5))
    O = 2.0 * c[None, :] * np.ones((8, 1))
    scores = y64 @ O - c * c
    return int(np.argmax(scores))

