def getd(st, k, bits, epw):
    w = k // epw
    if w >= 6:
        return 0
    v = int(st[w])
    return (v >> (bits * (k % epw))) & ((1 << bits) - 1)

def putd(st, k, val, bits, epw):
    w = k // epw
    if w >= 6:
        return
    v = int(st[w])
    sh = bits * (k % epw)
    v = (v & ~(((1 << bits) - 1) << sh)) | (val << sh)
    st[w] = np.float32(v)

def cfg(layout):
    T = layout['T']
    bits = max(1, (T - 1).bit_length())
    return T, bits, 24 // bits

def init(layout):
    return np.zeros(16, dtype=np.float32)

def update(state, token):
    return upd(state, token, LAYOUT)

LAYOUT = {}

def upd(st, t, lay):
    T, bits, epw = cfg(lay)
    xb = lay['x_base']; yb = lay['y_base']; zb = lay['z_base']
    p = int(st[6]) - 1
    if t == lay['QSEP']:
        if p >= 0 and p < 1000:
            st[7] = np.float32(p + 1)
            st[6] = np.float32(0)
        return st
    isx = xb <= t < xb + T
    isy = yb <= t < yb + T
    isz = zb <= t < zb + T
    if p < 0:
        if isx or isy:
            st[6] = np.float32(t + 1)
        return st
    px = xb <= p < xb + T
    py = yb <= p < yb + T
    if px and isy:
        putd(st, p - xb, t - yb, bits, epw)
        st[6] = np.float32(0)
    elif py and isz:
        putd(st, T + p - yb, t - zb, bits, epw)
        st[6] = np.float32(0)
    elif isx or isy:
        st[6] = np.float32(t + 1)
    else:
        st[6] = np.float32(0)
    return st

def predict(state):
    lay = LAYOUT
    T, bits, epw = cfg(lay)
    q = int(state[7]) - 1
    if q < 0:
        return lay['z_base']
    x = q - lay['x_base']
    g = getd(state, x, bits, epw)
    f = getd(state, T + g, bits, epw)
    return lay['z_base'] + f
